  // Player rollouts (Platform; server lib/ota-rollout.js)
  'nav.platform.rollouts': 'Player rollouts',
  'platform.tab.rollouts': 'Player rollouts',
  'platform.rollouts.title': 'Player rollouts',
  'platform.rollouts.subtitle': 'New player versions reach screens in waves, and stop themselves if they do worse',
  'platform.rollouts.desc': 'A new Android, Pi or Windows player goes to 10% of that platform\'s screens, then 50%, then everyone, each wave waiting until the updated screens look healthy. If updated screens crash or go dark more than the rest, the rollout halts by itself and you are emailed. Pi and Windows screens that took a halted version are sent back to the previous one. Android cannot go back to an older version, so there a halt stops the spread and the fix is a newer build. Screens on the beta channel, and a Force update, skip the waves.',
  'platform.rollouts.disabled': 'Waves are off on this server (OTA_STAGED_ROLLOUT=off): every screen is offered a new version at once.',
