  'auto.hint.emergency': 'Shows an emergency alert on screens, the same way an emergency feed does. Sending the same alert id again changes nothing; a clear ends it.',
  'auto.hint.mass_notification': 'For mass notification systems. Accepts CAP 1.2 XML, or JSON from Alertus, InformaCast and similar systems. Alerts are matched on the sender\'s own alert id, so a repeat or a retry shows once and a clear ends it.',
