  // 3.0: Simple help and the install-statistics question, now translated
  'simple.help.g1.title': "Connect a screen",
  'simple.help.g1.s1': "On the TV, tablet or computer you want to use, open the player: install the Android app, or open this site's /player page in its web browser.",
  'simple.help.g1.s2': "No TV handy? Open the player in another browser tab to try it.",
  'simple.help.g1.s3': "The player shows a 6-digit code. Here, choose \"Add a screen\" and type it in.",
  'simple.help.g1.s4': "Give the screen a name you will recognise, like \"Front window\".",
  'simple.help.g2.title': "Change what a screen shows",
  'simple.help.g2.s1': "Choose \"Change what a screen shows\", or tap the screen under \"Your screens\".",
  'simple.help.g2.s2': "Pick \"Replace\" to show only the new things, or \"Add\" to keep what is already playing.",
  'simple.help.g2.s3': "Upload photos or videos, pick ones you uploaded before, or show the same as another screen.",
  'simple.help.g2.s4': "The screen updates within a few seconds.",
  'simple.help.g3.title': "Upload photos and videos",
  'simple.help.g3.s1': "Choose \"Upload photos\" and pick as many files as you like, or drag them in.",
  'simple.help.g3.s2': "Tick the screens that should show them, or untick them all to keep them for later.",
  'simple.help.g3.s3': "Photos show for 10 seconds each; videos play to the end.",
  'simple.help.q1': "What can I use as a screen?",
  'simple.help.a1': "Android TVs, TV boxes and tablets, Fire TV, LG and Samsung smart TVs, Raspberry Pi, Windows and ChromeOS — or any device with a web browser.",
  'simple.help.q2': "My screen is not changing. What should I check?",
  'simple.help.a2': "Make sure the screen shows \"Playing\" on the home page. If it says \"Offline\", check that the device is on and connected to the internet; it picks up your changes as soon as it reconnects.",
  'simple.help.q3': "What happens if the internet goes down?",
  'simple.help.a3': "Screens keep the content locally and carry on playing it. New changes arrive when the connection comes back.",
  'simple.help.q4': "Which files can I upload?",
  'simple.help.a4': "Photos (JPEG, PNG, GIF, WebP) and videos (MP4 works best), plus audio. PDFs can be uploaded from the Content page in Advanced view.",
  'simple.help.q5': "How do I rename or remove a screen?",
  'simple.help.a5': "Switch to Advanced (top right), open Screens, click the screen, then use Rename or Remove at the top of its page.",
  'simple.help.q6': "Can I show different things at different times of day?",
  'simple.help.a6': "Yes — that is Schedule, in Advanced view. Simple view always shows the same content on a screen until you change it.",
  'simple.help.trial_q': "How does the free trial work?",
  'simple.help.trial_a': "You get 14 days of the Pro plan with every feature unlocked and no card required. When it ends you move to the Free plan: nothing is deleted, and screens beyond the Free plan pause until you choose a plan.",
  'stats.prompt.title': "Help show how widely ScreenTinker is deployed?",
  'stats.prompt.body': "Because most installs are private, we can't tell how many screens are out there. Sharing sends a random ID, the version, and how many screens you run — nothing else, ever. You can change this any time in Settings.",
  'stats.prompt.share': "Share",
  'stats.prompt.no': "No thanks",
  'stats.prompt.thanks': "Thank you — sharing install statistics",
  // 3.0: Simple view, workspaces and view-only members
