  'migrate.how.xibo': 'In Xibo, open Administration, then Applications, and add an Application with "Client Credentials" ticked. Copy its Client ID and Client Secret. Enter your CMS address (the one you sign in at), for example https://cms.example.com.',
  'migrate.how.yodeck': 'In Yodeck, open Account Settings, Advanced Settings, API Tokens, and generate a token (Premium or Enterprise plan). Paste it as label:token. Yodeck does not hand out original uploaded images and documents through its API: those are listed so you can add them with the zip import. Videos come over as the version Yodeck plays.',
  'migrate.how.optisigns': 'OptiSigns has an API, but it does not document any way to download your files, so a playlist would arrive empty. Download your files from OptiSigns and use the zip import: one folder per playlist, or a playlists.csv.',
  'migrate.how.screencloud': 'In ScreenCloud Studio, open Account Settings, then the Developer tab, and create a token with read permissions. Choose the region shown there (EU or US). ScreenCloud keeps time rules on individual channel items; those are listed, not imported.',
  'migrate.how.anthias': 'Enter the address of your Anthias device, for example http://192.168.1.20. If you turned on authentication, enter its username and password. Each device is imported as one screen with one playlist.',
